suspend fun fetchUser(id: String): Result<User> = runCatching {
    api.getUser(id)
}

fetchUser("123")
    .onSuccess { user -> updateUi(user) }
    .onFailure { error -> showError(error.message ?: "Unknown error") }

// or fold for a single expression
val displayName = fetchUser("123").fold(
    onSuccess = { it.name },
    onFailure = { "Guest" }
)

// Result<T> - fine for a simple utility
fun parseJson(raw: String): Result<Config> = runCatching { Json.decodeFromString(raw) }

// sealed hierarchy - better for domain logic with distinct error types
sealed class LoginResult {
    data class Success(val token: String) : LoginResult()
    data object InvalidCredentials : LoginResult()
    data object AccountLocked : LoginResult()
    data class NetworkError(val cause: Throwable) : LoginResult()
}
